frappe.ui.form.on('Sales Order', {
    refresh(frm) {
        kniterp_so_apply_shipping_party_query(frm);
    },
    customer(frm) {
        // Re-apply after ERPNext resets the query on customer change
        setTimeout(() => kniterp_so_apply_shipping_party_query(frm), 500);
    },
    custom_shipping_party(frm) {
        kniterp_so_apply_shipping_party_query(frm);
        frm.set_value('shipping_address_name', '');
        if (frm.doc.custom_shipping_party) {
            frappe.call({
                method: 'frappe.contacts.doctype.address.address.get_default_address',
                args: { doctype: 'Customer', name: frm.doc.custom_shipping_party },
                callback(r) {
                    if (r.message) frm.set_value('shipping_address_name', r.message);
                }
            });
        }
    }
});

function kniterp_so_apply_shipping_party_query(frm) {
    const party = frm.doc.custom_shipping_party || frm.doc.customer;
    if (!party) return;
    frm.set_query('shipping_address_name', () => ({
        query: 'frappe.contacts.doctype.address.address.address_query',
        filters: { link_doctype: 'Customer', link_name: party }
    }));
}

